/// <summary>Whole days an invoice has been overdue, in UTC; 0 when it is not overdue.</summary>
public int DaysOverdue(Invoice invoice) =>
    IsOverdue(invoice) ? (int)Math.Floor((_clock.UtcNow - invoice.DueUtc).TotalDays) : 0;

